/**
 * The header and the library are of different ABI versions.
 */
#define MIMI_ERR_ABI 1

/**
 * Called from another thread than the one that called `mimi_init`.
 */
#define MIMI_ERR_WRONG_THREAD 2

/**
 * NULL, invalid UTF-8, or a value out of range.
 */
#define MIMI_ERR_INVALID_ARGUMENT 3

/**
 * The account is not open.
 */
#define MIMI_ERR_NOT_CONNECTED 4

/**
 * No such room.
 */
#define MIMI_ERR_NO_SUCH_ROOM 5

/**
 * No such message.
 */
#define MIMI_ERR_NO_SUCH_MESSAGE 6

/**
 * No such invite.
 */
#define MIMI_ERR_NO_SUCH_INVITE 7

/**
 * No such device.
 */
#define MIMI_ERR_NO_SUCH_DEVICE 8

/**
 * The room's policy refuses it.
 */
#define MIMI_ERR_NOT_PERMITTED 9

/**
 * The hub refused it.
 */
#define MIMI_ERR_REFUSED 10

/**
 * Text or a file past a limit.
 */
#define MIMI_ERR_TOO_LARGE 11

/**
 * The provider could not be reached, or the stream failed.
 */
#define MIMI_ERR_NETWORK 12

/**
 * The provider refused the token, or no token is stored.
 */
#define MIMI_ERR_UNAUTHORIZED 13

/**
 * The provider does not serve mimid's live stream.
 */
#define MIMI_ERR_STREAM_OFF 14

/**
 * The token belongs to another user.
 */
#define MIMI_ERR_WRONG_USER 15

/**
 * Another instance holds the state and did not release it.
 */
#define MIMI_ERR_LOCKED 16

/**
 * Another instance took this account over.
 */
#define MIMI_ERR_TAKEN_OVER 17

/**
 * The state lock file was removed or replaced under us.
 */
#define MIMI_ERR_LOCK_LOST 18

/**
 * The state directory or database cannot be used.
 */
#define MIMI_ERR_STATE 19

/**
 * A local file could not be read or written.
 */
#define MIMI_ERR_IO 20

/**
 * The library panicked; the account, if any, is closed.
 */
#define MIMI_ERR_PANIC 21

/**
 * The account panicked before and was closed.
 */
#define MIMI_ERR_POISONED 22

/**
 * Anything else; the text says what.
 */
#define MIMI_ERR_INTERNAL 23

/**
 * `mimi_init` was not called, or `mimi_shutdown` was.
 */
#define MIMI_ERR_NOT_INITIALIZED 24

/**
 * No log events.
 */
#define MIMI_LOG_NONE 0

/**
 * Errors.
 */
#define MIMI_LOG_ERROR 1

/**
 * Warnings and errors.
 */
#define MIMI_LOG_WARN 2

/**
 * Information too.
 */
#define MIMI_LOG_INFO 3

/**
 * Debugging too.
 */
#define MIMI_LOG_DEBUG 4

/**
 * Everything.
 */
#define MIMI_LOG_TRACE 5

/**
 * Invites from users this user allowed; the rest wait. The default.
 */
#define MIMI_INVITES_FROM_ALLOWED 0

/**
 * Every invite.
 */
#define MIMI_INVITES_ANY 1

/**
 * None; every invite waits.
 */
#define MIMI_INVITES_NEVER 2

/**
 * A step of connecting: `step`, `steps`, `text`.
 */
#define MIMI_EV_PROGRESS 1

/**
 * The account is open; its token is now kept in the state directory.
 */
#define MIMI_EV_CONNECTED 2

/**
 * The account is closed by a failure or a takeover: `status`,
 * `temporary`, `text`. Never sent after `mimi_account_close`.
 */
#define MIMI_EV_DISCONNECTED 3

/**
 * A log line: `level`, `text`; `account` is NULL.
 */
#define MIMI_EV_LOG 11

